    const col = this.cols.get(ringKey(cx, cz));
    if (!col || !this.isHydrated(cx, cz)) return false;
    writeCell(col, (x & 15) * 16 + (z & 15), y, b, meta);
    this.invalidateLight(cx, cz);
    this.light.clear();
    this.lastKey = NaN;
    this.version++;
